 if(/라이브러리|프레임워크|SDK|API|엔진|도구|레퍼런스|자산/.test(e.kind)){ if(d==='제작 도구'||d==='레퍼런스')return 'tool';if(d==='아이콘·모션·VFX 구현')return 'tool';if(d==='게임 구현')return 'game';return 'code'}
