function codeArt(e,seed){let typ=e.domain==='웹·CSS'?'css':e.domain==='Python·데스크톱'?'python':e.domain==='게임 구현'?'game':'web';let snippets={css:`<span class="purple">.component</span> {\n  display: <span class="mint">grid</span>;\n  gap: <span class="pink">16px</span>;\n  transition: <span class="mint">all .2s</span>;\n}`,python:`<span class="purple">from</span> ui <span class="purple">import</span> app\n\nwindow = <span class="mint">App</span>()\nwindow.<span class="pink">show</span>()`,game:`<span class="purple">func</span> <span class="mint">_process</span>(dt):\n  motion += input * dt\n  update_viewport()`,web:`<span class="purple">const</span> preview = (data) =&gt; {\n  <span class="purple">return</span> <span class="mint">render</span>(data);\n};`};return `<div class="demo-scale"><div class="mock-code"><div class="code-h"><i></i><i></i><i></i></div><pre>${snippets[typ]}</pre></div></div>`}
