function motionVisual(e,k,caption){let body='';const box=(cls,extra='')=>`<div class="native-shape ${cls}" ${extra}>✦</div>`;
 if(['stagger','sequence','parallel','reorder'].includes(k))body=`<div class="motion-row">${[0,1,2].map(i=>box('native-'+k,`style="--i:${i}"`)).join('')}</div>`;
 else if(k==='crossfade')body=`<div class="native-shape native-cross-a">A</div><div class="native-shape native-cross-b">B</div>`;
 else if(k==='typewriter')body='<div class="native-typewriter">Motion creates meaning.</div>';
 else if(k==='stroke')body='<svg width="210" height="100" viewBox="0 0 210 100"><path class="native-stroke" d="M15 77 Q44 4 83 52 T195 22" fill="none" stroke="#6174ef" stroke-width="6" stroke-linecap="round"/></svg>';
 else if(k==='ripple')body='<div class="native-ripple"></div><div class="native-core">✓</div>';
 else if(k==='toggle')body='<div class="native-toggle-track"><i></i></div>';
 else if(k==='ticker')body='<div class="native-ticker">128<span>129<br>130<br>131</span></div>';
 else if(k==='tabmotion')body='<div class="native-tabs"><span>Overview</span><span>Analytics</span><span>Settings</span><i></i></div>';
 else if(['accordionmotion','drawermotion','sheetmotion','modalmotion'].includes(k))body=`<div class="native-window"><i></i><i></i><i></i><div class="native-${k}">${k==='accordionmotion'?'Details':'Panel'}</div></div>`;
 else if(k.startsWith('ease-')||['delay','duration'].includes(k))body=`<div class="motion-lanes"><label>${esc(caption)}</label><div><i class="native-traveler" style="animation-timing-function:${{'ease-linear':'linear','ease-in':'ease-in','ease-out':'ease-out','ease-in-out':'ease-in-out','ease-steps':'steps(5,end)'}[k]||'linear'};${k==='delay'?'animation-delay:1s;':''}"></i></div><small>0 → 1</small></div>`;
 else if(['burst','confetti'].includes(k))body=`<div class="native-particle-stage">${Array.from({length:14},(_,i)=>`<i class="native-${k}" style="--i:${i};--dx:${Math.cos(i/14*6.28)*75}px;--dy:${Math.sin(i/14*6.28)*55}px;--c:${palette[i%5]}"></i>`).join('')}</div>`;
 else body=box('native-'+k);
 return `<div class="native-motion" data-motion-key="${k}">${body}<div class="native-motion-caption">${esc(caption)}</div></div>`;}

