 if(['lightning','tracer','slash','weapontrail','trail','ribbon','beam','muzzle'].includes(k)){
  const d=k==='lightning'?'M159 22 117 84h34l-20 73 59-94h-34Z':k==='slash'||k==='weapontrail'?'M42 142 Q130 12 259 58 Q142 21 42 142Z':k==='ribbon'?'M32 104 C77 4 118 169 164 83S243 39 271 95':'M37 112 263 63';return stage(`<svg viewBox="0 0 300 190"><path class="effect-stroke" d="${d}" fill="${['slash','weapontrail','lightning'].includes(k)?'#aabaff':'none'}" stroke="${k==='muzzle'?'#ffcf82':'#9ec7ff'}" stroke-width="${k==='beam'?12:k==='ribbon'?9:3}" stroke-linecap="round"/></svg>`);}
 if(['fresnel','bloom','shield','depthfade'].includes(k))return stage('<div class="effect-orb"></div>');
 if(['uvpan','uvdistort','flipbook'].includes(k))return stage(`<div class="effect-tiles">${Array.from({length:k==='flipbook'?8:24},(_,i)=>`<i>${k==='flipbook'?i+1:''}</i>`).join('')}</div>`);
